// main.ts
var _ = __toESM(require_lodash());
function toTitleCase(str) {
  return str.replace(/\w\S*/g, function(txt) {
    return txt.charAt(0).toUpperCase() + txt.substr(1).toLowerCase();
  });
}
var specialCases = {
  xMens: "X-men",
  sciFiGuns: "Sci-fi guns",
  twentiethCenturyEnglishs: "20th Century English",
  englishs: "English"
};
function toPretty(str) {
  if (_.has(specialCases, str)) {
    return specialCases[str];
  }
  if (str.includes("_")) {
    return str.split("_").map(toPretty).join(" ");
  } else if (str.slice(1).toLowerCase() != str.slice(1)) {
    const num = str.slice(1).search(/[A-Z]/);
    return [str.slice(0, num + 1), str.slice(num + 1)].map(toPretty).join(" ");
  } else {
    return toTitleCase(str);
  }
}
var RandomNames = class extends import_obsidian.Plugin {
  async onload() {
    _.keys(choices).sort().forEach((first) => {
      _.keys(choices[first]).sort().forEach((second) => {
        this.addCommand({
          id: `${first}-${second}`,
          name: `Insert name (${toPretty(first)} - ${toPretty(second)})`,
          editorCallback: (editor, view) => {
            editor.replaceRange(
              choices[first][second](),
              editor.getCursor()
            );
          }
        });
      });
    });
  }
};
